const fs = require('fs'), path = require('path')
const files = {}

files["supabase/migrations/005_barbershop.sql"] = "-- ============================================================\n-- FYP.STUDIO — Módulo Barbería (y Belleza)\n-- Ejecutar DESPUÉS de 004_verticals.sql\n-- ============================================================\n\n-- ── Sucursales ────────────────────────────────────────────────\ncreate table if not exists branches (\n  id           uuid primary key default uuid_generate_v4(),\n  business_id  uuid not null references businesses(id) on delete cascade,\n  name         text not null,\n  address      text,\n  phone        text,\n  whatsapp     text,\n  city         text,\n  is_main      boolean not null default false,\n  active       boolean not null default true,\n  created_at   timestamptz not null default now()\n);\n\ncreate index if not exists idx_branches_business on branches(business_id, active);\nalter table branches enable row level security;\ncreate policy \"comercio gestiona branches\"\n  on branches for all\n  using  (business_id = get_my_business_id() or is_superadmin())\n  with check (business_id = get_my_business_id() or is_superadmin());\n\n-- ── Staff (barberos / profesionales) ─────────────────────────\ncreate table if not exists staff (\n  id           uuid primary key default uuid_generate_v4(),\n  business_id  uuid not null references businesses(id) on delete cascade,\n  branch_id    uuid references branches(id) on delete set null,\n  name         text not null,\n  role         text not null default 'barber', -- barber, stylist, specialist\n  bio          text,\n  avatar_url   text,\n  phone        text,\n  color        text not null default '#1565FF', -- color en el calendario\n  active       boolean not null default true,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now()\n);\n\ncreate index if not exists idx_staff_business on staff(business_id, active);\nalter table staff enable row level security;\ncreate policy \"comercio gestiona staff\"\n  on staff for all\n  using  (business_id = get_my_business_id() or is_superadmin())\n  with check (business_id = get_my_business_id() or is_superadmin());\ncreate policy \"tienda publica lee staff activo\"\n  on staff for select using (active = true);\n\ncreate trigger set_updated_at_staff\n  before update on staff\n  for each row execute function update_updated_at();\n\n-- ── Horarios por staff ────────────────────────────────────────\n-- Qué días trabaja y en qué horario\ncreate table if not exists staff_schedules (\n  id           uuid primary key default uuid_generate_v4(),\n  staff_id     uuid not null references staff(id) on delete cascade,\n  business_id  uuid not null references businesses(id) on delete cascade,\n  day_of_week  int not null check (day_of_week between 0 and 6), -- 0=Dom, 1=Lun...\n  start_time   time not null,  -- '09:00'\n  end_time     time not null,  -- '18:00'\n  break_start  time,           -- '13:00' (opcional)\n  break_end    time,           -- '14:00'\n  is_working   boolean not null default true,\n  unique(staff_id, day_of_week)\n);\n\nalter table staff_schedules enable row level security;\ncreate policy \"comercio gestiona staff_schedules\"\n  on staff_schedules for all\n  using  (business_id = get_my_business_id() or is_superadmin())\n  with check (business_id = get_my_business_id() or is_superadmin());\ncreate policy \"tienda publica lee schedules\"\n  on staff_schedules for select using (is_working = true);\n\n-- ── Turnos/Appointments ───────────────────────────────────────\n-- (reemplaza/extiende la tabla appointments de 004)\ncreate table if not exists bookings (\n  id              uuid primary key default uuid_generate_v4(),\n  business_id     uuid not null references businesses(id) on delete cascade,\n  branch_id       uuid references branches(id) on delete set null,\n  staff_id        uuid references staff(id) on delete set null,\n  product_id      uuid references products(id) on delete set null, -- servicio\n  customer_name   text not null,\n  customer_phone  text,\n  customer_email  text,\n  date            date not null,\n  start_time      time not null,\n  end_time        time not null,\n  duration_min    int not null default 30,\n  status          text not null default 'pending'\n                    check (status in ('pending','confirmed','done','cancelled','noshow')),\n  notes           text,\n  price           numeric(10,2),\n  source          text default 'store', -- store, admin, whatsapp\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now()\n);\n\ncreate index if not exists idx_bookings_business  on bookings(business_id, date);\ncreate index if not exists idx_bookings_staff     on bookings(staff_id, date);\ncreate index if not exists idx_bookings_date      on bookings(business_id, date, status);\n\nalter table bookings enable row level security;\ncreate policy \"comercio gestiona bookings\"\n  on bookings for all\n  using  (business_id = get_my_business_id() or is_superadmin())\n  with check (business_id = get_my_business_id() or is_superadmin());\ncreate policy \"api inserta bookings\"\n  on bookings for insert with check (true);\n\ncreate trigger set_updated_at_bookings\n  before update on bookings\n  for each row execute function update_updated_at();\n\n-- Realtime para bookings (dashboard admin live)\nalter publication supabase_realtime add table bookings;\nalter publication supabase_realtime add table staff;\n\n-- ── Page Builder config ───────────────────────────────────────\n-- Configuración visual de la tienda pública\nalter table businesses\n  add column if not exists page_config jsonb default null;\n-- Estructura: { hero, sections, theme, fonts, layout }\n\n-- ── Insertar sucursal principal automáticamente ───────────────\n-- (trigger para nuevos negocios con vertical barbershop/beauty)\ncreate or replace function create_main_branch()\nreturns trigger language plpgsql as $$\nbegin\n  if new.vertical_type in ('barbershop','beauty') then\n    insert into branches (business_id, name, is_main, active)\n    values (new.id, 'Sucursal principal', true, true)\n    on conflict do nothing;\n  end if;\n  return new;\nend;\n$$;\n\ncreate trigger trg_create_main_branch\n  after insert on businesses\n  for each row execute function create_main_branch();\n"

files["types/index.ts"] = "export type Plan = 'basic' | 'pro' | 'premium'\nexport type SubscriptionStatus = 'trial' | 'active' | 'past_due' | 'canceled' | 'suspended'\nexport type OrderStatus = 'pending' | 'confirmed' | 'preparing' | 'ready' | 'shipped' | 'delivered' | 'cancelled'\nexport type PaymentStatus = 'unpaid' | 'paid' | 'refunded'\nexport type DeliveryType = 'delivery' | 'pickup'\nexport type UserRole = 'owner' | 'staff' | 'superadmin'\nexport type AIGenerationType = 'product' | 'promo' | 'insights'\n\nexport interface Business {\n  id: string; name: string; slug: string; description?: string | null\n  logo_url?: string | null; banner_url?: string | null; whatsapp?: string | null\n  address?: string | null; currency: string; primary_color: string\n  secondary_color: string; plan: Plan; active: boolean\n  subscription_status: SubscriptionStatus; subscription_expires_at?: string | null\n  instagram?: string | null; facebook?: string | null; tiktok?: string | null\n  website?: string | null; vertical_type?: string | null; enabled_modules?: string[] | null; created_at: string; updated_at: string\n}\n\nexport interface Profile {\n  id: string; user_id: string; business_id: string\n  role: UserRole; created_at: string; business?: Business\n}\n\nexport interface Category {\n  id: string; business_id: string; name: string; slug: string\n  sort_order: number; active: boolean; created_at: string\n}\n\nexport interface Product {\n  id: string; business_id: string; category_id?: string | null\n  name: string; slug: string; description?: string | null; price: number\n  images: string[]; tags: string[]; stock?: number | null; featured: boolean\n  active: boolean; seo_title?: string | null; seo_desc?: string | null\n  created_at: string; updated_at: string; category?: Category | null\n}\n\nexport interface Customer {\n  id: string; business_id: string; name: string; phone?: string | null\n  address?: string | null; email?: string | null; total_orders: number\n  total_spent: number; created_at: string; updated_at: string\n}\n\nexport interface Order {\n  id: string; business_id: string; customer_id?: string | null\n  order_number: number; status: OrderStatus; payment_status: PaymentStatus\n  confirmed_sale: boolean; delivery_type: DeliveryType; subtotal: number\n  total: number; comment?: string | null; customer_name: string\n  customer_phone?: string | null; customer_address?: string | null\n  created_at: string; updated_at: string; items?: OrderItem[]; customer?: Customer | null\n}\n\nexport interface OrderItem {\n  id: string; order_id: string; product_id?: string | null\n  product_name: string; unit_price: number; quantity: number; subtotal: number\n  product?: Product | null\n}\n\nexport interface CartItem { product: Product; quantity: number }\n\nexport interface CheckoutFormData {\n  name: string; phone: string; address?: string\n  delivery_type: DeliveryType; comment?: string\n}\n\nexport interface CreateOrderResponse { orderId: string; orderNumber: number }\n\nexport interface AIProductOutput {\n  name: string; description: string; category: string; tags: string[]\n  instagram_copy: string; whatsapp_copy: string; hashtags: string[]\n  seo_title: string; seo_description: string\n}\n\nexport interface AIPromoOutput {\n  title: string; body: string; instagram_story: string\n  whatsapp_message: string; cta: string\n}\n\nexport interface DashboardStats {\n  pendingOrders: number; confirmedOrders: number; totalRevenue: number\n  todayRevenue: number; totalProducts: number; totalCustomers: number\n  recentOrders: Order[]; topProducts: { name: string; count: number; revenue: number }[]\n  cancelRate?: number\n}\n\n// ── Inventario ────────────────────────────────────────────────\n\nexport interface InventoryCategory {\n  id: string\n  business_id: string\n  name: string\n  color: string\n  icon: string\n  created_at: string\n}\n\nexport type MovementType = 'entrada' | 'salida' | 'ajuste' | 'devolucion'\n\nexport interface InventoryItem {\n  id: string\n  business_id: string\n  category_id?: string | null\n  product_id?: string | null\n  name: string\n  sku?: string | null\n  unit: string\n  stock_current: number\n  stock_min: number\n  stock_max?: number | null\n  cost_price?: number | null\n  supplier?: string | null\n  notes?: string | null\n  active: boolean\n  created_at: string\n  updated_at: string\n  // joins\n  category?: InventoryCategory | null\n  product?: { name: string } | null\n}\n\nexport interface InventoryMovement {\n  id: string\n  business_id: string\n  item_id: string\n  order_id?: string | null\n  type: MovementType\n  quantity: number\n  stock_before: number\n  stock_after: number\n  reason?: string | null\n  created_by?: string | null\n  created_at: string\n  item?: InventoryItem | null\n}\n\nexport type StockStatus = 'ok' | 'low' | 'critical' | 'out'\n\nexport function getStockStatus(item: InventoryItem): StockStatus {\n  if (item.stock_current <= 0) return 'out'\n  if (item.stock_current <= item.stock_min * 0.5) return 'critical'\n  if (item.stock_current <= item.stock_min) return 'low'\n  return 'ok'\n}\n\n// ── Proveedores ───────────────────────────────────────────────\n\nexport interface Supplier {\n  id: string\n  business_id: string\n  name: string\n  contact_name?: string | null\n  phone?: string | null\n  email?: string | null\n  address?: string | null\n  city?: string | null\n  notes?: string | null\n  active: boolean\n  created_at: string\n  updated_at: string\n  // computed\n  products?: SupplierProduct[]\n}\n\nexport interface SupplierProduct {\n  id: string\n  supplier_id: string\n  business_id: string\n  inventory_item_id?: string | null\n  product_name: string\n  sku_supplier?: string | null\n  unit: string\n  price?: number | null\n  min_order?: number | null\n  lead_days?: number | null\n  notes?: string | null\n  created_at: string\n  updated_at: string\n  // join\n  inventory_item?: { name: string } | null\n}\n\n// ── Barbería / Belleza ────────────────────────────────────────\n\nexport interface Branch {\n  id: string\n  business_id: string\n  name: string\n  address?: string | null\n  phone?: string | null\n  whatsapp?: string | null\n  city?: string | null\n  is_main: boolean\n  active: boolean\n  created_at: string\n}\n\nexport interface Staff {\n  id: string\n  business_id: string\n  branch_id?: string | null\n  name: string\n  role: string\n  bio?: string | null\n  avatar_url?: string | null\n  phone?: string | null\n  color: string\n  active: boolean\n  created_at: string\n  updated_at: string\n  branch?: Branch | null\n}\n\nexport interface StaffSchedule {\n  id: string\n  staff_id: string\n  business_id: string\n  day_of_week: number  // 0=Dom, 1=Lun, 2=Mar...\n  start_time: string   // '09:00'\n  end_time: string     // '18:00'\n  break_start?: string | null\n  break_end?: string | null\n  is_working: boolean\n}\n\nexport type BookingStatus = 'pending' | 'confirmed' | 'done' | 'cancelled' | 'noshow'\n\nexport interface Booking {\n  id: string\n  business_id: string\n  branch_id?: string | null\n  staff_id?: string | null\n  product_id?: string | null\n  customer_name: string\n  customer_phone?: string | null\n  customer_email?: string | null\n  date: string         // 'YYYY-MM-DD'\n  start_time: string   // 'HH:MM'\n  end_time: string\n  duration_min: number\n  status: BookingStatus\n  notes?: string | null\n  price?: number | null\n  source: string\n  created_at: string\n  updated_at: string\n  // joins\n  staff?: Staff | null\n  branch?: Branch | null\n  product?: { name: string; price: number } | null\n}\n\n// Page Builder\nexport interface PageConfig {\n  theme: {\n    primaryColor: string\n    secondaryColor: string\n    bgColor: string\n    textColor: string\n    font: string\n    borderRadius: 'none' | 'sm' | 'md' | 'lg' | 'full'\n    style: 'modern' | 'minimal' | 'bold' | 'elegant'\n  }\n  hero: {\n    enabled: boolean\n    title: string\n    subtitle: string\n    ctaText: string\n    ctaAction: 'book' | 'whatsapp' | 'scroll'\n    backgroundType: 'color' | 'image' | 'gradient'\n    backgroundValue: string\n  }\n  sections: PageSection[]\n}\n\nexport interface PageSection {\n  id: string\n  type: 'services' | 'team' | 'gallery' | 'testimonials' | 'contact' | 'hours' | 'promo'\n  enabled: boolean\n  title: string\n  order: number\n}\n"

files["app/admin/barbershop/page.tsx"] = "// app/admin/barbershop/page.tsx — Hub del módulo barbería\nimport { createClient } from '@/lib/supabase/server'\nimport { redirect } from 'next/navigation'\nimport BarbershopHub from './BarbershopHub'\nimport type { Booking, Staff, Branch, Product } from '@/types'\n\nexport const metadata = { title: 'Agenda' }\nexport const dynamic = 'force-dynamic'\n\nexport default async function BarbershopPage() {\n  const supabase = await createClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) redirect('/auth/login')\n\n  const { data: profile } = await supabase\n    .from('profiles')\n    .select('business_id, business:businesses(name, currency, whatsapp, primary_color)')\n    .eq('user_id', user.id)\n    .single()\n\n  if (!profile?.business_id) redirect('/admin/onboarding')\n\n  const bid = profile.business_id\n  const biz = profile.business as { name: string; currency: string; whatsapp?: string; primary_color: string } | null\n\n  const today = new Date().toISOString().split('T')[0]\n\n  const [bookingsRes, staffRes, branchesRes, servicesRes] = await Promise.all([\n    supabase\n      .from('bookings')\n      .select('*, staff:staff(name,color), branch:branches(name), product:products(name,price)')\n      .eq('business_id', bid)\n      .gte('date', today)\n      .order('date').order('start_time')\n      .limit(200),\n    supabase\n      .from('staff')\n      .select('*, branch:branches(name)')\n      .eq('business_id', bid)\n      .eq('active', true)\n      .order('name'),\n    supabase\n      .from('branches')\n      .select('*')\n      .eq('business_id', bid)\n      .eq('active', true)\n      .order('is_main', { ascending: false }),\n    supabase\n      .from('products')\n      .select('id, name, price, description')\n      .eq('business_id', bid)\n      .eq('active', true)\n      .order('name'),\n  ])\n\n  return (\n    <BarbershopHub\n      businessId={bid}\n      businessName={biz?.name ?? ''}\n      currency={biz?.currency ?? 'UYU'}\n      whatsapp={biz?.whatsapp ?? ''}\n      primaryColor={biz?.primary_color ?? '#1565FF'}\n      bookings={(bookingsRes.data ?? []) as Booking[]}\n      staff={(staffRes.data ?? []) as Staff[]}\n      branches={(branchesRes.data ?? []) as Branch[]}\n      services={(servicesRes.data ?? []) as Product[]}\n    />\n  )\n}\n"

files["app/admin/barbershop/BarbershopHub.tsx"] = "// app/admin/barbershop/BarbershopHub.tsx\n'use client'\nimport { useState, useMemo } from 'react'\nimport { createClient } from '@/lib/supabase/client'\nimport {\n  Calendar, Users, Clock, MapPin, Plus, ChevronLeft, ChevronRight,\n  Check, X, Phone, MessageCircle, Edit2, Trash2, Loader2,\n  AlertCircle, Settings, MoreHorizontal, Building2,\n} from 'lucide-react'\nimport { cn, formatPrice } from '@/lib/utils'\nimport type { Booking, Staff, Branch, Product, BookingStatus } from '@/types'\n\ninterface Props {\n  businessId: string; businessName: string; currency: string\n  whatsapp: string; primaryColor: string\n  bookings: Booking[]; staff: Staff[]; branches: Branch[]; services: Product[]\n}\n\ntype Tab = 'agenda' | 'staff' | 'branches'\n\nconst DAYS_ES = ['Dom','Lun','Mar','Mié','Jue','Vie','Sáb']\nconst DAYS_FULL = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado']\nconst MONTHS_ES = ['Enero','Febrero','Marzo','Abril','Mayo','Junio',\n  'Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre']\n\nconst STATUS_CFG: Record<BookingStatus, { label:string; bg:string; text:string; dot:string }> = {\n  pending:   { label:'Pendiente',   bg:'bg-amber-50',  text:'text-amber-700',  dot:'bg-amber-400'  },\n  confirmed: { label:'Confirmado',  bg:'bg-blue-50',   text:'text-blue-700',   dot:'bg-blue-500'   },\n  done:      { label:'Realizado',   bg:'bg-green-50',  text:'text-green-700',  dot:'bg-green-500'  },\n  cancelled: { label:'Cancelado',   bg:'bg-red-50',    text:'text-red-600',    dot:'bg-red-400'    },\n  noshow:    { label:'No asistió',  bg:'bg-gray-100',  text:'text-gray-500',   dot:'bg-gray-400'   },\n}\n\nfunction StatusBadge({ status }: { status: BookingStatus }) {\n  const cfg = STATUS_CFG[status]\n  return (\n    <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-0.5 text-xs font-medium ${cfg.bg} ${cfg.text}`}>\n      <span className={`h-1.5 w-1.5 rounded-full ${cfg.dot}`}/>\n      {cfg.label}\n    </span>\n  )\n}\n\n// Generar slots de tiempo cada N minutos\nfunction generateSlots(start: string, end: string, step = 30): string[] {\n  const slots: string[] = []\n  const [sh,sm] = start.split(':').map(Number)\n  const [eh,em] = end.split(':').map(Number)\n  let cur = sh*60+sm\n  const endMin = eh*60+em\n  while (cur < endMin) {\n    const h = Math.floor(cur/60).toString().padStart(2,'0')\n    const m = (cur%60).toString().padStart(2,'0')\n    slots.push(`${h}:${m}`)\n    cur += step\n  }\n  return slots\n}\n\nexport default function BarbershopHub({\n  businessId, businessName, currency, whatsapp, primaryColor,\n  bookings: initialBookings, staff, branches, services,\n}: Props) {\n  const supabase = createClient()\n  const [tab,          setTab]          = useState<Tab>('agenda')\n  const [bookings,     setBookings]     = useState<Booking[]>(initialBookings)\n  const [selectedDate, setSelectedDate] = useState(new Date())\n  const [filterStaff,  setFilterStaff]  = useState<string|null>(null)\n  const [filterBranch, setFilterBranch] = useState<string|null>(null)\n  const [showNewBooking, setShowNewBooking] = useState(false)\n  const [editingBooking,  setEditingBooking]  = useState<Booking|null>(null)\n\n  const dateStr = selectedDate.toISOString().split('T')[0]\n\n  // Turnos del día seleccionado\n  const todayBookings = useMemo(() => {\n    let list = bookings.filter(b => b.date === dateStr)\n    if (filterStaff)  list = list.filter(b => b.staff_id === filterStaff)\n    if (filterBranch) list = list.filter(b => b.branch_id === filterBranch)\n    return list.sort((a,b) => a.start_time.localeCompare(b.start_time))\n  }, [bookings, dateStr, filterStaff, filterBranch])\n\n  // Stats del día\n  const confirmed = todayBookings.filter(b=>b.status==='confirmed'||b.status==='done').length\n  const pending   = todayBookings.filter(b=>b.status==='pending').length\n  const revenue   = todayBookings.filter(b=>b.status==='done').reduce((a,b)=>a+(b.price??0),0)\n\n  // Navegar fecha\n  function prevDay() { const d=new Date(selectedDate); d.setDate(d.getDate()-1); setSelectedDate(d) }\n  function nextDay() { const d=new Date(selectedDate); d.setDate(d.getDate()+1); setSelectedDate(d) }\n  function goToday() { setSelectedDate(new Date()) }\n\n  const isToday = dateStr === new Date().toISOString().split('T')[0]\n\n  async function updateStatus(id: string, status: BookingStatus) {\n    await supabase.from('bookings').update({ status }).eq('id', id)\n    setBookings(prev => prev.map(b => b.id===id ? {...b,status} : b))\n  }\n\n  async function deleteBooking(id: string) {\n    if (!confirm('¿Eliminar este turno?')) return\n    await supabase.from('bookings').delete().eq('id', id)\n    setBookings(prev => prev.filter(b => b.id !== id))\n  }\n\n  return (\n    <div className=\"space-y-4 animate-fade-in pb-4\">\n\n      {/* Header */}\n      <div className=\"flex items-start justify-between gap-3\">\n        <div>\n          <h1 className=\"text-xl lg:text-2xl font-bold text-gray-900 tracking-tight\">Agenda</h1>\n          <p className=\"text-xs text-gray-400 mt-0.5\">{businessName}</p>\n        </div>\n        <button onClick={() => setShowNewBooking(true)}\n          className=\"flex items-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold\n                     text-white active:scale-[0.98] transition-all\"\n          style={{ background: primaryColor }}>\n          <Plus size={15} />\n          <span className=\"hidden sm:inline\">Nuevo turno</span>\n          <span className=\"sm:hidden\">Nuevo</span>\n        </button>\n      </div>\n\n      {/* Tabs */}\n      <div className=\"flex items-center gap-1 bg-gray-100 rounded-xl p-1 w-fit\">\n        {([\n          { key:'agenda',   label:'Agenda',     icon: Calendar   },\n          { key:'staff',    label:'Barberos',   icon: Users      },\n          { key:'branches', label:'Sucursales', icon: Building2  },\n        ] as { key:Tab; label:string; icon:React.ElementType }[]).map(({ key, label, icon: Icon }) => (\n          <button key={key} onClick={() => setTab(key)}\n            className={cn('flex items-center gap-1.5 rounded-lg px-3 py-2 text-xs font-medium transition-all',\n              tab===key ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500 hover:text-gray-700')}>\n            <Icon size={13} />{label}\n          </button>\n        ))}\n      </div>\n\n      {/* ── TAB AGENDA ── */}\n      {tab === 'agenda' && (\n        <div className=\"space-y-4\">\n          {/* Navegación fecha */}\n          <div className=\"flex items-center gap-3\">\n            <button onClick={prevDay}\n              className=\"flex h-9 w-9 items-center justify-center rounded-xl border border-gray-200\n                         bg-white text-gray-500 hover:bg-gray-50 transition-all\">\n              <ChevronLeft size={16}/>\n            </button>\n\n            <div className=\"flex-1 text-center\">\n              <p className=\"text-sm font-bold text-gray-900\">\n                {DAYS_FULL[selectedDate.getDay()]}{' '}\n                {selectedDate.getDate()} de{' '}\n                {MONTHS_ES[selectedDate.getMonth()]}\n              </p>\n              {!isToday && (\n                <button onClick={goToday} className=\"text-xs mt-0.5 hover:underline\"\n                  style={{ color: primaryColor }}>\n                  Ir a hoy\n                </button>\n              )}\n            </div>\n\n            <button onClick={nextDay}\n              className=\"flex h-9 w-9 items-center justify-center rounded-xl border border-gray-200\n                         bg-white text-gray-500 hover:bg-gray-50 transition-all\">\n              <ChevronRight size={16}/>\n            </button>\n          </div>\n\n          {/* Filtros */}\n          {(staff.length > 1 || branches.length > 1) && (\n            <div className=\"flex items-center gap-2 overflow-x-auto pb-1 scrollbar-hide\">\n              <select value={filterStaff??''} onChange={e=>setFilterStaff(e.target.value||null)}\n                className=\"rounded-xl border border-gray-200 bg-white px-3 py-1.5 text-xs text-gray-700 shrink-0\">\n                <option value=\"\">Todos los barberos</option>\n                {staff.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}\n              </select>\n              {branches.length > 1 && (\n                <select value={filterBranch??''} onChange={e=>setFilterBranch(e.target.value||null)}\n                  className=\"rounded-xl border border-gray-200 bg-white px-3 py-1.5 text-xs text-gray-700 shrink-0\">\n                  <option value=\"\">Todas las sucursales</option>\n                  {branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}\n                </select>\n              )}\n            </div>\n          )}\n\n          {/* Stats del día */}\n          <div className=\"grid grid-cols-3 gap-3\">\n            {[\n              { label:'Turnos', value:todayBookings.length, color:'text-gray-900' },\n              { label:'Confirmados', value:confirmed, color:'text-blue-600' },\n              { label:'Pendientes', value:pending, color: pending>0?'text-amber-600':'text-gray-400' },\n            ].map(({label,value,color})=>(\n              <div key={label} className=\"bg-white rounded-2xl border border-gray-100 p-3 text-center shadow-sm\">\n                <p className={`text-xl font-bold ${color}`}>{value}</p>\n                <p className=\"text-[10px] text-gray-400 mt-0.5\">{label}</p>\n              </div>\n            ))}\n          </div>\n\n          {/* Lista de turnos */}\n          {todayBookings.length === 0 ? (\n            <div className=\"rounded-2xl border-2 border-dashed border-gray-200 py-14 text-center\">\n              <Calendar size={28} className=\"mx-auto text-gray-200 mb-3\"/>\n              <p className=\"text-sm font-medium text-gray-400\">Sin turnos para este día</p>\n              <button onClick={() => setShowNewBooking(true)}\n                className=\"mt-3 text-xs font-semibold hover:underline\"\n                style={{ color: primaryColor }}>\n                + Agregar turno\n              </button>\n            </div>\n          ) : (\n            <div className=\"space-y-2\">\n              {todayBookings.map(booking => (\n                <BookingCard\n                  key={booking.id}\n                  booking={booking}\n                  currency={currency}\n                  whatsapp={whatsapp}\n                  onStatusChange={updateStatus}\n                  onEdit={() => setEditingBooking(booking)}\n                  onDelete={() => deleteBooking(booking.id)}\n                  primaryColor={primaryColor}\n                />\n              ))}\n            </div>\n          )}\n        </div>\n      )}\n\n      {/* ── TAB STAFF ── */}\n      {tab === 'staff' && (\n        <StaffTab\n          businessId={businessId}\n          staff={staff}\n          branches={branches}\n          primaryColor={primaryColor}\n        />\n      )}\n\n      {/* ── TAB BRANCHES ── */}\n      {tab === 'branches' && (\n        <BranchesTab\n          businessId={businessId}\n          branches={branches}\n          primaryColor={primaryColor}\n        />\n      )}\n\n      {/* Modal nuevo/editar turno */}\n      {(showNewBooking || editingBooking) && (\n        <BookingModal\n          businessId={businessId}\n          staff={staff}\n          branches={branches}\n          services={services}\n          booking={editingBooking}\n          selectedDate={dateStr}\n          existingBookings={bookings}\n          onClose={() => { setShowNewBooking(false); setEditingBooking(null) }}\n          onSave={(saved) => {\n            setBookings(prev =>\n              editingBooking\n                ? prev.map(b => b.id===saved.id ? saved : b)\n                : [...prev, saved]\n            )\n            setShowNewBooking(false)\n            setEditingBooking(null)\n          }}\n          primaryColor={primaryColor}\n        />\n      )}\n    </div>\n  )\n}\n\n// ── Booking Card ──────────────────────────────────────────────\nfunction BookingCard({ booking, currency, whatsapp, onStatusChange, onEdit, onDelete, primaryColor }: {\n  booking: Booking; currency: string; whatsapp: string\n  onStatusChange: (id:string,s:BookingStatus)=>void\n  onEdit: ()=>void; onDelete: ()=>void; primaryColor: string\n}) {\n  const [menuOpen, setMenuOpen] = useState(false)\n  const waLink = booking.customer_phone\n    ? `https://wa.me/${booking.customer_phone.replace(/\\D/g,'')}?text=${encodeURIComponent(\n        `Hola ${booking.customer_name}! Te confirmamos tu turno para el ${booking.date} a las ${booking.start_time}.`\n      )}`\n    : null\n\n  return (\n    <div className=\"bg-white rounded-2xl border border-gray-100 overflow-hidden shadow-sm\">\n      <div className=\"flex items-start gap-3 p-4\">\n        {/* Hora + color staff */}\n        <div className=\"shrink-0 text-center min-w-[48px]\">\n          <div className=\"h-10 w-10 rounded-xl flex items-center justify-center text-white text-xs font-bold\"\n            style={{ background: booking.staff?.color ?? primaryColor }}>\n            {booking.start_time.slice(0,5)}\n          </div>\n          <p className=\"text-[10px] text-gray-400 mt-1\">{booking.end_time.slice(0,5)}</p>\n        </div>\n\n        {/* Info */}\n        <div className=\"flex-1 min-w-0\">\n          <div className=\"flex items-start justify-between gap-2\">\n            <div>\n              <p className=\"text-sm font-bold text-gray-900\">{booking.customer_name}</p>\n              {booking.product && (\n                <p className=\"text-xs text-gray-500 mt-0.5\">{booking.product.name}</p>\n              )}\n              {booking.staff && (\n                <p className=\"text-xs text-gray-400\">✂️ {booking.staff.name}</p>\n              )}\n              {booking.branch && (\n                <p className=\"text-xs text-gray-400\">📍 {booking.branch.name}</p>\n              )}\n            </div>\n            <StatusBadge status={booking.status}/>\n          </div>\n\n          {/* Precio */}\n          {booking.price != null && (\n            <p className=\"text-sm font-bold mt-1.5\" style={{ color: primaryColor }}>\n              {formatPrice(booking.price, currency)}\n            </p>\n          )}\n\n          {/* Acciones */}\n          <div className=\"flex items-center gap-2 mt-3 flex-wrap\">\n            {booking.status === 'pending' && (\n              <button onClick={() => onStatusChange(booking.id,'confirmed')}\n                className=\"flex items-center gap-1 rounded-xl px-3 py-1.5 text-xs font-semibold text-white\"\n                style={{ background: primaryColor }}>\n                <Check size={11}/> Confirmar\n              </button>\n            )}\n            {(booking.status==='confirmed'||booking.status==='pending') && (\n              <button onClick={() => onStatusChange(booking.id,'done')}\n                className=\"flex items-center gap-1 rounded-xl px-3 py-1.5 text-xs font-semibold\n                           bg-green-500 text-white\">\n                <Check size={11}/> Realizado\n              </button>\n            )}\n            {waLink && (\n              <a href={waLink} target=\"_blank\"\n                className=\"flex items-center gap-1 rounded-xl px-3 py-1.5 text-xs font-semibold\n                           bg-green-500 text-white\">\n                <MessageCircle size={11}/> WA\n              </a>\n            )}\n            <div className=\"relative ml-auto\">\n              <button onClick={() => setMenuOpen(o=>!o)}\n                className=\"flex h-7 w-7 items-center justify-center rounded-lg text-gray-400\n                           hover:bg-gray-100 transition-colors\">\n                <MoreHorizontal size={14}/>\n              </button>\n              {menuOpen && (\n                <>\n                  <div className=\"fixed inset-0 z-10\" onClick={() => setMenuOpen(false)}/>\n                  <div className=\"absolute right-0 top-8 z-20 w-36 rounded-xl border border-gray-200\n                                  bg-white py-1 shadow-lg\">\n                    <button onClick={()=>{onEdit();setMenuOpen(false)}}\n                      className=\"w-full flex items-center gap-2 px-3 py-2 text-xs text-gray-700 hover:bg-gray-50\">\n                      <Edit2 size={12}/> Editar\n                    </button>\n                    <button onClick={()=>onStatusChange(booking.id,'cancelled')}\n                      className=\"w-full flex items-center gap-2 px-3 py-2 text-xs text-red-600 hover:bg-red-50\">\n                      <X size={12}/> Cancelar\n                    </button>\n                    <button onClick={()=>{onDelete();setMenuOpen(false)}}\n                      className=\"w-full flex items-center gap-2 px-3 py-2 text-xs text-red-600 hover:bg-red-50\">\n                      <Trash2 size={12}/> Eliminar\n                    </button>\n                  </div>\n                </>\n              )}\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  )\n}\n\n// ── Modal Booking ─────────────────────────────────────────────\nfunction BookingModal({ businessId, staff, branches, services, booking, selectedDate,\n  existingBookings, onClose, onSave, primaryColor }: {\n  businessId:string; staff:Staff[]; branches:Branch[]; services:Product[]\n  booking:Booking|null; selectedDate:string; existingBookings:Booking[]\n  onClose:()=>void; onSave:(b:Booking)=>void; primaryColor:string\n}) {\n  const supabase = createClient()\n  const [loading,  setLoading]  = useState(false)\n  const [error,    setError]    = useState<string|null>(null)\n\n  const [customerName,  setCustomerName]  = useState(booking?.customer_name ?? '')\n  const [customerPhone, setCustomerPhone] = useState(booking?.customer_phone ?? '')\n  const [staffId,       setStaffId]       = useState(booking?.staff_id ?? (staff[0]?.id ?? ''))\n  const [branchId,      setBranchId]      = useState(booking?.branch_id ?? (branches[0]?.id ?? ''))\n  const [serviceId,     setServiceId]     = useState(booking?.product_id ?? '')\n  const [date,          setDate]          = useState(booking?.date ?? selectedDate)\n  const [startTime,     setStartTime]     = useState(booking?.start_time ?? '09:00')\n  const [duration,      setDuration]      = useState(booking?.duration_min ?? 30)\n  const [price,         setPrice]         = useState(booking?.price?.toString() ?? '')\n  const [notes,         setNotes]         = useState(booking?.notes ?? '')\n  const [status,        setStatus]        = useState<BookingStatus>(booking?.status ?? 'confirmed')\n\n  // Calcular end_time\n  const [sh, sm] = startTime.split(':').map(Number)\n  const endMin = sh*60 + sm + duration\n  const endTime = `${Math.floor(endMin/60).toString().padStart(2,'0')}:${(endMin%60).toString().padStart(2,'0')}`\n\n  // Verificar conflictos\n  const hasConflict = existingBookings.some(b => {\n    if (b.id === booking?.id) return false\n    if (b.staff_id !== staffId || b.date !== date) return false\n    if (b.status === 'cancelled' || b.status === 'noshow') return false\n    const bStart = b.start_time.slice(0,5)\n    const bEnd   = b.end_time.slice(0,5)\n    return startTime < bEnd && endTime > bStart\n  })\n\n  // Auto-completar precio desde servicio\n  function handleServiceChange(id: string) {\n    setServiceId(id)\n    const svc = services.find(s=>s.id===id)\n    if (svc?.price) setPrice(svc.price.toString())\n  }\n\n  async function handleSave(e: React.FormEvent) {\n    e.preventDefault()\n    if (hasConflict) { setError('Hay un conflicto de horario con otro turno'); return }\n    setLoading(true); setError(null)\n    try {\n      const payload = {\n        business_id:    businessId,\n        staff_id:       staffId || null,\n        branch_id:      branchId || null,\n        product_id:     serviceId || null,\n        customer_name:  customerName.trim(),\n        customer_phone: customerPhone.trim() || null,\n        date,\n        start_time:     startTime,\n        end_time:       endTime,\n        duration_min:   duration,\n        price:          price ? parseFloat(price) : null,\n        notes:          notes.trim() || null,\n        status,\n        source:         'admin',\n      }\n      if (booking) {\n        const { data,error:e } = await supabase.from('bookings')\n          .update(payload).eq('id',booking.id)\n          .select('*, staff:staff(name,color), branch:branches(name), product:products(name,price)')\n          .single()\n        if (e) throw e; onSave(data as Booking)\n      } else {\n        const { data,error:e } = await supabase.from('bookings')\n          .insert(payload)\n          .select('*, staff:staff(name,color), branch:branches(name), product:products(name,price)')\n          .single()\n        if (e) throw e; onSave(data as Booking)\n      }\n    } catch(e:unknown) {\n      setError(e instanceof Error?e.message:'Error al guardar')\n    } finally { setLoading(false) }\n  }\n\n  return (\n    <div className=\"fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4\">\n      <div className=\"absolute inset-0 bg-black/40 backdrop-blur-sm\" onClick={onClose}/>\n      <div className=\"relative bg-white w-full sm:max-w-lg rounded-t-3xl sm:rounded-2xl\n                      shadow-2xl max-h-[92vh] overflow-y-auto animate-slide-up\">\n        {/* Handle mobile */}\n        <div className=\"flex justify-center pt-3 pb-1 sm:hidden\">\n          <div className=\"h-1 w-10 rounded-full bg-gray-200\"/>\n        </div>\n\n        <div className=\"flex items-center justify-between px-5 py-4 border-b border-gray-100 sticky top-0 bg-white z-10\">\n          <p className=\"font-bold text-gray-900\">{booking ? 'Editar turno' : 'Nuevo turno'}</p>\n          <button onClick={onClose}\n            className=\"h-8 w-8 flex items-center justify-center rounded-xl text-gray-400\n                       hover:bg-gray-100 transition-colors\">\n            <X size={16}/>\n          </button>\n        </div>\n\n        <form onSubmit={handleSave} className=\"p-5 space-y-4\">\n          {/* Cliente */}\n          <div className=\"grid grid-cols-2 gap-3\">\n            <div className=\"col-span-2\">\n              <label className=\"field-label\">Nombre del cliente <span className=\"text-red-400\">*</span></label>\n              <input type=\"text\" required value={customerName} onChange={e=>setCustomerName(e.target.value)}\n                placeholder=\"Nombre completo\" className=\"input-base\"/>\n            </div>\n            <div className=\"col-span-2\">\n              <label className=\"field-label\">Teléfono / WhatsApp</label>\n              <input type=\"tel\" value={customerPhone} onChange={e=>setCustomerPhone(e.target.value)}\n                placeholder=\"099123456\" className=\"input-base\" inputMode=\"numeric\"/>\n            </div>\n          </div>\n\n          {/* Servicio */}\n          {services.length > 0 && (\n            <div>\n              <label className=\"field-label\">Servicio</label>\n              <select value={serviceId} onChange={e=>handleServiceChange(e.target.value)} className=\"input-base\">\n                <option value=\"\">Sin especificar</option>\n                {services.map(s=><option key={s.id} value={s.id}>{s.name} — ${s.price}</option>)}\n              </select>\n            </div>\n          )}\n\n          {/* Barbero + Sucursal */}\n          <div className=\"grid grid-cols-2 gap-3\">\n            {staff.length > 0 && (\n              <div>\n                <label className=\"field-label\">Barbero</label>\n                <select value={staffId} onChange={e=>setStaffId(e.target.value)} className=\"input-base\">\n                  <option value=\"\">Sin asignar</option>\n                  {staff.map(s=>(\n                    <option key={s.id} value={s.id}>{s.name}</option>\n                  ))}\n                </select>\n              </div>\n            )}\n            {branches.length > 1 && (\n              <div>\n                <label className=\"field-label\">Sucursal</label>\n                <select value={branchId} onChange={e=>setBranchId(e.target.value)} className=\"input-base\">\n                  {branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}\n                </select>\n              </div>\n            )}\n          </div>\n\n          {/* Fecha + Hora */}\n          <div className=\"grid grid-cols-2 gap-3\">\n            <div>\n              <label className=\"field-label\">Fecha</label>\n              <input type=\"date\" value={date} onChange={e=>setDate(e.target.value)} className=\"input-base\"/>\n            </div>\n            <div>\n              <label className=\"field-label\">Hora inicio</label>\n              <input type=\"time\" value={startTime} onChange={e=>setStartTime(e.target.value)} className=\"input-base\"/>\n            </div>\n          </div>\n\n          {/* Duración */}\n          <div className=\"grid grid-cols-2 gap-3\">\n            <div>\n              <label className=\"field-label\">Duración (min)</label>\n              <select value={duration} onChange={e=>setDuration(parseInt(e.target.value))} className=\"input-base\">\n                {[15,20,30,45,60,90,120].map(d=>(\n                  <option key={d} value={d}>{d} min</option>\n                ))}\n              </select>\n            </div>\n            <div>\n              <label className=\"field-label\">Fin estimado</label>\n              <input type=\"text\" value={endTime} readOnly\n                className=\"input-base bg-gray-50 text-gray-500 cursor-not-allowed\"/>\n            </div>\n          </div>\n\n          {/* Conflicto */}\n          {hasConflict && (\n            <div className=\"flex items-center gap-2 rounded-xl bg-red-50 border border-red-100 px-4 py-3\">\n              <AlertCircle size={14} className=\"text-red-500 shrink-0\"/>\n              <p className=\"text-xs text-red-700 font-medium\">\n                ⚠️ Este barbero ya tiene un turno en ese horario\n              </p>\n            </div>\n          )}\n\n          {/* Precio + Estado */}\n          <div className=\"grid grid-cols-2 gap-3\">\n            <div>\n              <label className=\"field-label\">Precio</label>\n              <input type=\"number\" min=\"0\" step=\"0.01\" value={price}\n                onChange={e=>setPrice(e.target.value)} placeholder=\"0\" className=\"input-base\"/>\n            </div>\n            <div>\n              <label className=\"field-label\">Estado</label>\n              <select value={status} onChange={e=>setStatus(e.target.value as BookingStatus)} className=\"input-base\">\n                <option value=\"pending\">Pendiente</option>\n                <option value=\"confirmed\">Confirmado</option>\n                <option value=\"done\">Realizado</option>\n                <option value=\"cancelled\">Cancelado</option>\n                <option value=\"noshow\">No asistió</option>\n              </select>\n            </div>\n          </div>\n\n          <div>\n            <label className=\"field-label\">Notas</label>\n            <textarea value={notes} onChange={e=>setNotes(e.target.value)} rows={2}\n              placeholder=\"Observaciones del turno...\" className=\"input-base resize-none\"/>\n          </div>\n\n          {error && (\n            <div className=\"rounded-xl bg-red-50 px-4 py-3 text-sm text-red-700\">{error}</div>\n          )}\n\n          <div className=\"flex gap-3 pt-2 pb-2\">\n            <button type=\"submit\" disabled={loading||hasConflict}\n              className=\"flex-1 flex items-center justify-center gap-2 rounded-xl py-3\n                         text-sm font-semibold text-white disabled:opacity-40\"\n              style={{ background: primaryColor }}>\n              {loading&&<Loader2 size={14} className=\"animate-spin\"/>}\n              {loading?'Guardando...':booking?'Guardar cambios':'Crear turno'}\n            </button>\n            <button type=\"button\" onClick={onClose}\n              className=\"rounded-xl border border-gray-200 px-5 py-3 text-sm font-medium text-gray-600\">\n              Cancelar\n            </button>\n          </div>\n        </form>\n      </div>\n    </div>\n  )\n}\n\n// ── Staff Tab ─────────────────────────────────────────────────\nfunction StaffTab({ businessId, staff, branches, primaryColor }: {\n  businessId:string; staff:Staff[]; branches:Branch[]; primaryColor:string\n}) {\n  const supabase = createClient()\n  const [list, setList] = useState<Staff[]>(staff)\n  const [showForm, setShowForm] = useState(false)\n  const [editing, setEditing] = useState<Staff|null>(null)\n\n  const COLORS = ['#1565FF','#0B3EAB','#EC4899','#7C3AED','#059669','#D97706','#DC2626','#374151']\n\n  const [name,     setName]     = useState('')\n  const [role,     setRole]     = useState('barber')\n  const [bio,      setBio]      = useState('')\n  const [color,    setColor]    = useState('#1565FF')\n  const [branchId, setBranchId] = useState(branches[0]?.id ?? '')\n  const [loading,  setLoading]  = useState(false)\n\n  function openEdit(s: Staff) {\n    setEditing(s); setName(s.name); setRole(s.role)\n    setBio(s.bio??''); setColor(s.color); setBranchId(s.branch_id??'')\n    setShowForm(true)\n  }\n\n  function resetForm() {\n    setEditing(null); setName(''); setRole('barber')\n    setBio(''); setColor('#1565FF'); setBranchId(branches[0]?.id??'')\n  }\n\n  async function handleSave(e: React.FormEvent) {\n    e.preventDefault()\n    if (!name.trim()) return\n    setLoading(true)\n    const payload = {\n      business_id: businessId, name:name.trim(), role, bio:bio.trim()||null,\n      color, branch_id:branchId||null, active:true,\n    }\n    if (editing) {\n      const { data } = await supabase.from('staff').update(payload).eq('id',editing.id).select('*').single()\n      if (data) setList(prev=>prev.map(s=>s.id===editing.id?data as Staff:s))\n    } else {\n      const { data } = await supabase.from('staff').insert(payload).select('*').single()\n      if (data) setList(prev=>[...prev,data as Staff])\n    }\n    setLoading(false); setShowForm(false); resetForm()\n  }\n\n  async function toggleActive(id: string, active: boolean) {\n    await supabase.from('staff').update({ active: !active }).eq('id', id)\n    setList(prev=>prev.map(s=>s.id===id?{...s,active:!active}:s))\n  }\n\n  return (\n    <div className=\"space-y-4\">\n      <div className=\"flex items-center justify-between\">\n        <p className=\"text-sm text-gray-500\">{list.length} barberos registrados</p>\n        <button onClick={() => { resetForm(); setShowForm(true) }}\n          className=\"flex items-center gap-2 rounded-xl px-4 py-2 text-sm font-semibold text-white\"\n          style={{ background: primaryColor }}>\n          <Plus size={14}/> Agregar\n        </button>\n      </div>\n\n      {list.length === 0 ? (\n        <div className=\"rounded-2xl border-2 border-dashed border-gray-200 py-12 text-center\">\n          <Users size={24} className=\"mx-auto text-gray-200 mb-2\"/>\n          <p className=\"text-sm text-gray-400\">Sin barberos registrados</p>\n        </div>\n      ) : (\n        <div className=\"space-y-2\">\n          {list.map(s => (\n            <div key={s.id} className=\"flex items-center gap-3 bg-white rounded-2xl border border-gray-100 p-4\">\n              <div className=\"h-10 w-10 rounded-xl flex items-center justify-center text-white\n                              text-sm font-bold shrink-0\"\n                style={{ background: s.color }}>\n                {s.name.slice(0,1).toUpperCase()}\n              </div>\n              <div className=\"flex-1 min-w-0\">\n                <p className=\"text-sm font-bold text-gray-900\">{s.name}</p>\n                <p className=\"text-xs text-gray-400 capitalize\">{s.role} {s.branch?.name ? `· ${s.branch.name}` : ''}</p>\n                {s.bio && <p className=\"text-xs text-gray-400 truncate mt-0.5\">{s.bio}</p>}\n              </div>\n              <div className=\"flex items-center gap-1 shrink-0\">\n                <button onClick={() => openEdit(s)}\n                  className=\"h-8 w-8 flex items-center justify-center rounded-lg text-gray-400\n                             hover:bg-gray-100 transition-colors\">\n                  <Edit2 size={13}/>\n                </button>\n                <button onClick={() => toggleActive(s.id, s.active)}\n                  className={cn('h-8 w-8 flex items-center justify-center rounded-lg transition-colors',\n                    s.active ? 'text-green-500 hover:bg-green-50' : 'text-gray-300 hover:bg-gray-100')}>\n                  <Check size={13}/>\n                </button>\n              </div>\n            </div>\n          ))}\n        </div>\n      )}\n\n      {/* Form modal */}\n      {showForm && (\n        <div className=\"fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4\">\n          <div className=\"absolute inset-0 bg-black/40 backdrop-blur-sm\" onClick={()=>{setShowForm(false);resetForm()}}/>\n          <div className=\"relative bg-white w-full sm:max-w-md rounded-t-3xl sm:rounded-2xl\n                          shadow-2xl max-h-[85vh] overflow-y-auto\">\n            <div className=\"flex justify-center pt-3 pb-1 sm:hidden\">\n              <div className=\"h-1 w-10 rounded-full bg-gray-200\"/>\n            </div>\n            <div className=\"px-5 py-4 border-b border-gray-100\">\n              <p className=\"font-bold text-gray-900\">{editing?'Editar barbero':'Nuevo barbero'}</p>\n            </div>\n            <form onSubmit={handleSave} className=\"p-5 space-y-4\">\n              <div>\n                <label className=\"field-label\">Nombre <span className=\"text-red-400\">*</span></label>\n                <input type=\"text\" required value={name} onChange={e=>setName(e.target.value)}\n                  placeholder=\"Nombre del barbero\" className=\"input-base\"/>\n              </div>\n              <div className=\"grid grid-cols-2 gap-3\">\n                <div>\n                  <label className=\"field-label\">Rol</label>\n                  <select value={role} onChange={e=>setRole(e.target.value)} className=\"input-base\">\n                    <option value=\"barber\">Barbero</option>\n                    <option value=\"stylist\">Estilista</option>\n                    <option value=\"specialist\">Especialista</option>\n                  </select>\n                </div>\n                {branches.length > 1 && (\n                  <div>\n                    <label className=\"field-label\">Sucursal</label>\n                    <select value={branchId} onChange={e=>setBranchId(e.target.value)} className=\"input-base\">\n                      {branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}\n                    </select>\n                  </div>\n                )}\n              </div>\n              <div>\n                <label className=\"field-label\">Color en agenda</label>\n                <div className=\"flex items-center gap-2 flex-wrap\">\n                  {COLORS.map(c=>(\n                    <button key={c} type=\"button\" onClick={()=>setColor(c)}\n                      className={cn('h-8 w-8 rounded-xl transition-all',\n                        color===c?'ring-2 ring-offset-2 ring-gray-400 scale-110':'')}\n                      style={{background:c}}/>\n                  ))}\n                </div>\n              </div>\n              <div>\n                <label className=\"field-label\">Bio</label>\n                <textarea value={bio} onChange={e=>setBio(e.target.value)} rows={2}\n                  placeholder=\"Especialidad, años de experiencia...\" className=\"input-base resize-none\"/>\n              </div>\n              <div className=\"flex gap-3 pt-1 pb-2\">\n                <button type=\"submit\" disabled={loading}\n                  className=\"flex-1 flex items-center justify-center gap-2 rounded-xl py-3\n                             text-sm font-semibold text-white disabled:opacity-40\"\n                  style={{background:primaryColor}}>\n                  {loading&&<Loader2 size={13} className=\"animate-spin\"/>}\n                  {loading?'Guardando...':editing?'Guardar':'Agregar barbero'}\n                </button>\n                <button type=\"button\" onClick={()=>{setShowForm(false);resetForm()}}\n                  className=\"rounded-xl border border-gray-200 px-4 py-3 text-sm text-gray-600\">\n                  Cancelar\n                </button>\n              </div>\n            </form>\n          </div>\n        </div>\n      )}\n    </div>\n  )\n}\n\n// ── Branches Tab ──────────────────────────────────────────────\nfunction BranchesTab({ businessId, branches, primaryColor }: {\n  businessId:string; branches:Branch[]; primaryColor:string\n}) {\n  const supabase = createClient()\n  const [list,     setList]     = useState<Branch[]>(branches)\n  const [showForm, setShowForm] = useState(false)\n  const [loading,  setLoading]  = useState(false)\n  const [name,     setName]     = useState('')\n  const [address,  setAddress]  = useState('')\n  const [phone,    setPhone]    = useState('')\n  const [whatsapp, setWhatsapp] = useState('')\n  const [city,     setCity]     = useState('')\n\n  async function handleSave(e: React.FormEvent) {\n    e.preventDefault()\n    if (!name.trim()) return\n    setLoading(true)\n    const { data } = await supabase.from('branches').insert({\n      business_id:businessId, name:name.trim(),\n      address:address.trim()||null, phone:phone.trim()||null,\n      whatsapp:whatsapp.replace(/\\D/g,'')||null, city:city.trim()||null,\n      is_main:false, active:true,\n    }).select('*').single()\n    if (data) setList(prev=>[...prev,data as Branch])\n    setLoading(false); setShowForm(false)\n    setName('');setAddress('');setPhone('');setWhatsapp('');setCity('')\n  }\n\n  return (\n    <div className=\"space-y-4\">\n      <div className=\"flex items-center justify-between\">\n        <p className=\"text-sm text-gray-500\">{list.length} sucursales</p>\n        <button onClick={()=>setShowForm(true)}\n          className=\"flex items-center gap-2 rounded-xl px-4 py-2 text-sm font-semibold text-white\"\n          style={{background:primaryColor}}>\n          <Plus size={14}/> Nueva sucursal\n        </button>\n      </div>\n\n      <div className=\"space-y-2\">\n        {list.map(b=>(\n          <div key={b.id} className=\"bg-white rounded-2xl border border-gray-100 p-4\">\n            <div className=\"flex items-center gap-2 mb-2\">\n              <div className=\"h-8 w-8 rounded-xl flex items-center justify-center text-white text-xs\"\n                style={{background:primaryColor}}>\n                <Building2 size={14}/>\n              </div>\n              <div>\n                <p className=\"text-sm font-bold text-gray-900\">{b.name}</p>\n                {b.is_main && <span className=\"text-[10px] text-blue-600 font-medium\">Principal</span>}\n              </div>\n            </div>\n            {b.address&&<p className=\"text-xs text-gray-500 flex items-center gap-1\"><MapPin size={11}/>{b.address}{b.city?`, ${b.city}`:''}</p>}\n            {b.phone&&<p className=\"text-xs text-gray-500 flex items-center gap-1 mt-1\"><Phone size={11}/>{b.phone}</p>}\n            {b.whatsapp&&(\n              <a href={`https://wa.me/${b.whatsapp}`} target=\"_blank\"\n                className=\"inline-flex items-center gap-1 text-xs text-green-600 mt-1\">\n                <MessageCircle size={11}/>{b.whatsapp}\n              </a>\n            )}\n          </div>\n        ))}\n      </div>\n\n      {showForm && (\n        <div className=\"fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4\">\n          <div className=\"absolute inset-0 bg-black/40 backdrop-blur-sm\" onClick={()=>setShowForm(false)}/>\n          <div className=\"relative bg-white w-full sm:max-w-md rounded-t-3xl sm:rounded-2xl shadow-2xl\">\n            <div className=\"flex justify-center pt-3 pb-1 sm:hidden\">\n              <div className=\"h-1 w-10 rounded-full bg-gray-200\"/>\n            </div>\n            <div className=\"px-5 py-4 border-b border-gray-100\">\n              <p className=\"font-bold text-gray-900\">Nueva sucursal</p>\n            </div>\n            <form onSubmit={handleSave} className=\"p-5 space-y-3\">\n              <div>\n                <label className=\"field-label\">Nombre <span className=\"text-red-400\">*</span></label>\n                <input type=\"text\" required value={name} onChange={e=>setName(e.target.value)}\n                  placeholder=\"Ej: Sucursal Centro\" className=\"input-base\"/>\n              </div>\n              <div className=\"grid grid-cols-2 gap-3\">\n                <div>\n                  <label className=\"field-label\">Ciudad</label>\n                  <input type=\"text\" value={city} onChange={e=>setCity(e.target.value)}\n                    placeholder=\"Montevideo\" className=\"input-base\"/>\n                </div>\n                <div>\n                  <label className=\"field-label\">Teléfono</label>\n                  <input type=\"text\" value={phone} onChange={e=>setPhone(e.target.value)}\n                    placeholder=\"2900 0000\" className=\"input-base\"/>\n                </div>\n              </div>\n              <div>\n                <label className=\"field-label\">Dirección</label>\n                <input type=\"text\" value={address} onChange={e=>setAddress(e.target.value)}\n                  placeholder=\"Av. 18 de Julio 1234\" className=\"input-base\"/>\n              </div>\n              <div>\n                <label className=\"field-label\">WhatsApp</label>\n                <input type=\"text\" value={whatsapp} onChange={e=>setWhatsapp(e.target.value)}\n                  placeholder=\"59899000000\" className=\"input-base\" inputMode=\"numeric\"/>\n              </div>\n              <div className=\"flex gap-3 pt-2 pb-2\">\n                <button type=\"submit\" disabled={loading}\n                  className=\"flex-1 rounded-xl py-3 text-sm font-semibold text-white disabled:opacity-40\"\n                  style={{background:primaryColor}}>\n                  {loading?'Guardando...':'Crear sucursal'}\n                </button>\n                <button type=\"button\" onClick={()=>setShowForm(false)}\n                  className=\"rounded-xl border border-gray-200 px-4 py-3 text-sm text-gray-600\">\n                  Cancelar\n                </button>\n              </div>\n            </form>\n          </div>\n        </div>\n      )}\n    </div>\n  )\n}\n"

files["app/store/[slug]/book/page.tsx"] = "// app/store/[slug]/book/page.tsx — Reservas online para barbería/belleza\nimport { createClient } from '@/lib/supabase/server'\nimport { notFound } from 'next/navigation'\nimport BookingFlow from '@/components/barbershop/BookingFlow'\nimport type { Business, Staff, Product, Branch } from '@/types'\n\nexport const metadata = { title: 'Reservar turno' }\n\nexport default async function BookPage({ params }: { params: { slug: string } }) {\n  const supabase = await createClient()\n\n  const { data: business } = await supabase\n    .from('businesses')\n    .select('*')\n    .eq('slug', params.slug)\n    .eq('active', true)\n    .single()\n\n  if (!business) notFound()\n\n  const [staffRes, servicesRes, branchesRes] = await Promise.all([\n    supabase\n      .from('staff')\n      .select('*, schedules:staff_schedules(*)')\n      .eq('business_id', business.id)\n      .eq('active', true)\n      .order('name'),\n    supabase\n      .from('products')\n      .select('*')\n      .eq('business_id', business.id)\n      .eq('active', true)\n      .order('name'),\n    supabase\n      .from('branches')\n      .select('*')\n      .eq('business_id', business.id)\n      .eq('active', true)\n      .order('is_main', { ascending: false }),\n  ])\n\n  return (\n    <BookingFlow\n      business={business as Business}\n      staff={(staffRes.data ?? []) as (Staff & { schedules: unknown[] })[]}\n      services={(servicesRes.data ?? []) as Product[]}\n      branches={(branchesRes.data ?? []) as Branch[]}\n    />\n  )\n}\n"

files["components/barbershop/BookingFlow.tsx"] = "// components/barbershop/BookingFlow.tsx\n// Flujo completo de reserva online — mobile-first\n'use client'\nimport { useState, useMemo } from 'react'\nimport { useRouter } from 'next/navigation'\nimport {\n  ArrowLeft, ChevronRight, Check, Clock, Calendar,\n  MapPin, Scissors, Loader2, MessageCircle, User, Phone,\n} from 'lucide-react'\nimport { cn, formatPrice } from '@/lib/utils'\nimport type { Business, Staff, Product, Branch } from '@/types'\n\ninterface Props {\n  business: Business\n  staff: (Staff & { schedules: unknown[] })[]\n  services: Product[]\n  branches: Branch[]\n}\n\ntype Step = 'branch' | 'service' | 'staff' | 'datetime' | 'confirm'\n\nconst DAYS = ['Dom','Lun','Mar','Mié','Jue','Vie','Sáb']\nconst MONTHS = ['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic']\n\nfunction generateTimeSlots(start='09:00', end='19:00', step=30): string[] {\n  const slots: string[] = []\n  const [sh,sm]=start.split(':').map(Number)\n  const [eh,em]=end.split(':').map(Number)\n  let cur=sh*60+sm\n  while(cur<eh*60+em){ slots.push(`${Math.floor(cur/60).toString().padStart(2,'0')}:${(cur%60).toString().padStart(2,'0')}`); cur+=step }\n  return slots\n}\n\n// Generar próximos 14 días\nfunction getNextDays(count=14): Date[] {\n  const days: Date[] = []\n  const today = new Date(); today.setHours(0,0,0,0)\n  for(let i=0;i<count;i++){\n    const d=new Date(today); d.setDate(d.getDate()+i); days.push(d)\n  }\n  return days\n}\n\nexport default function BookingFlow({ business, staff, services, branches }: Props) {\n  const router = useRouter()\n  const color = business.primary_color ?? '#1565FF'\n  const currency = business.currency ?? 'UYU'\n\n  const steps: Step[] = [\n    ...(branches.length > 1 ? ['branch' as Step] : []),\n    'service', 'staff', 'datetime', 'confirm'\n  ]\n\n  const [stepIdx,       setStepIdx]       = useState(0)\n  const [selectedBranch,setSelectedBranch]= useState<Branch|null>(branches[0]??null)\n  const [selectedService,setSelectedService]= useState<Product|null>(null)\n  const [selectedStaff, setSelectedStaff] = useState<Staff|null>(null)\n  const [selectedDate,  setSelectedDate]  = useState<Date|null>(null)\n  const [selectedTime,  setSelectedTime]  = useState<string|null>(null)\n  const [customerName,  setCustomerName]  = useState('')\n  const [customerPhone, setCustomerPhone] = useState('')\n  const [notes,         setNotes]         = useState('')\n  const [submitting,    setSubmitting]    = useState(false)\n  const [done,          setDone]          = useState(false)\n  const [error,         setError]         = useState<string|null>(null)\n\n  const currentStep = steps[stepIdx]\n\n  const days = useMemo(() => getNextDays(14), [])\n  const timeSlots = generateTimeSlots('09:00','19:00',30)\n\n  function next() { if(stepIdx<steps.length-1) setStepIdx(s=>s+1) }\n  function prev() { if(stepIdx>0) setStepIdx(s=>s-1) }\n\n  // Calcular duración del servicio (default 30min)\n  const duration = 30\n  const endTime = selectedTime ? (() => {\n    const [h,m]=selectedTime.split(':').map(Number)\n    const end=h*60+m+duration\n    return `${Math.floor(end/60).toString().padStart(2,'0')}:${(end%60).toString().padStart(2,'0')}`\n  })() : ''\n\n  async function handleConfirm(e: React.FormEvent) {\n    e.preventDefault()\n    if(!customerName.trim()||!customerPhone.trim()||!selectedDate||!selectedTime) return\n    setSubmitting(true); setError(null)\n    try {\n      const dateStr = selectedDate.toISOString().split('T')[0]\n      const res = await fetch('/api/bookings', {\n        method:'POST',\n        headers:{'Content-Type':'application/json'},\n        body: JSON.stringify({\n          businessId:   business.id,\n          branchId:     selectedBranch?.id ?? null,\n          staffId:      selectedStaff?.id ?? null,\n          productId:    selectedService?.id ?? null,\n          customerName: customerName.trim(),\n          customerPhone:customerPhone.trim(),\n          date:         dateStr,\n          startTime:    selectedTime,\n          endTime,\n          durationMin:  duration,\n          price:        selectedService?.price ?? null,\n          notes:        notes.trim()||null,\n          source:       'store',\n        }),\n      })\n      if(!res.ok) { const d=await res.json(); throw new Error(d.error??'Error') }\n\n      // Abrir WhatsApp si tiene número configurado\n      if(business.whatsapp) {\n        const msg = encodeURIComponent(\n          `Hola! Acabo de reservar un turno:\\n\\n` +\n          `📅 Fecha: ${dateStr}\\n` +\n          `🕐 Hora: ${selectedTime}\\n` +\n          `${selectedService?`✂️ Servicio: ${selectedService.name}\\n`:'' }` +\n          `${selectedStaff?`👤 Barbero: ${selectedStaff.name}\\n`:'' }` +\n          `\\nNombre: ${customerName}\\nTeléfono: ${customerPhone}`\n        )\n        window.open(`https://wa.me/${business.whatsapp}?text=${msg}`,'_blank')\n      }\n      setDone(true)\n    } catch(e:unknown) {\n      setError(e instanceof Error?e.message:'Error al reservar')\n    } finally { setSubmitting(false) }\n  }\n\n  // ── PANTALLA FINAL ────────────────────────────────────────\n  if(done) return (\n    <div className=\"min-h-screen flex items-center justify-center p-6\" style={{background:'#F7F9FC'}}>\n      <div className=\"text-center max-w-sm w-full\">\n        <div className=\"h-20 w-20 rounded-full flex items-center justify-center mx-auto mb-5\"\n          style={{background:color+'18'}}>\n          <Check size={36} style={{color}}/>\n        </div>\n        <h1 className=\"text-2xl font-bold text-gray-900 mb-2\">¡Turno reservado!</h1>\n        <p className=\"text-sm text-gray-500 mb-6\">\n          Te esperamos el {selectedDate?.toLocaleDateString('es-UY',{weekday:'long',day:'numeric',month:'long'})} a las {selectedTime}hs\n        </p>\n        <div className=\"bg-white rounded-2xl border border-gray-100 p-4 text-left space-y-2 mb-6\">\n          {selectedService&&<p className=\"text-sm\"><span className=\"text-gray-400\">Servicio:</span> {selectedService.name}</p>}\n          {selectedStaff&&<p className=\"text-sm\"><span className=\"text-gray-400\">Barbero:</span> {selectedStaff.name}</p>}\n          {selectedBranch&&<p className=\"text-sm\"><span className=\"text-gray-400\">Sucursal:</span> {selectedBranch.name}</p>}\n        </div>\n        {business.whatsapp&&(\n          <p className=\"text-xs text-gray-400\">Se abrió WhatsApp para confirmar con el local</p>\n        )}\n        <button onClick={()=>router.push(`/store/${business.slug}`)}\n          className=\"mt-4 rounded-xl px-6 py-3 text-sm font-semibold text-white w-full\"\n          style={{background:color}}>\n          Volver a la tienda\n        </button>\n      </div>\n    </div>\n  )\n\n  return (\n    <div className=\"min-h-screen\" style={{background:'#F7F9FC'}}>\n      {/* Header */}\n      <header className=\"sticky top-0 z-10 bg-white border-b border-gray-100\">\n        <div className=\"max-w-lg mx-auto px-4 h-14 flex items-center gap-3\">\n          <button onClick={() => stepIdx>0 ? prev() : router.back()}\n            className=\"flex h-9 w-9 items-center justify-center rounded-xl text-gray-500\n                       hover:bg-gray-100 transition-colors\">\n            <ArrowLeft size={18}/>\n          </button>\n          <div className=\"flex items-center gap-2 flex-1\">\n            {business.logo_url\n              ? <img src={business.logo_url} alt=\"\" className=\"h-7 w-7 rounded-lg object-cover\"/>\n              : <div className=\"h-7 w-7 rounded-lg flex items-center justify-center text-white text-[10px] font-bold\"\n                  style={{background:color}}>{business.name.slice(0,2).toUpperCase()}</div>\n            }\n            <span className=\"font-semibold text-sm text-gray-900 truncate\">{business.name}</span>\n          </div>\n        </div>\n\n        {/* Progress bar */}\n        <div className=\"h-1 bg-gray-100\">\n          <div className=\"h-full transition-all duration-500\"\n            style={{width:`${((stepIdx+1)/steps.length)*100}%`,background:color}}/>\n        </div>\n      </header>\n\n      <div className=\"max-w-lg mx-auto px-4 py-6 pb-28\">\n\n        {/* ── STEP: BRANCH ── */}\n        {currentStep==='branch' && (\n          <div className=\"space-y-4 animate-fade-in\">\n            <div>\n              <h2 className=\"text-xl font-bold text-gray-900\">¿En qué sucursal?</h2>\n              <p className=\"text-sm text-gray-400 mt-1\">Elegí la ubicación que te quede mejor</p>\n            </div>\n            <div className=\"space-y-2\">\n              {branches.map(b=>(\n                <button key={b.id} onClick={()=>{setSelectedBranch(b);next()}}\n                  className={cn('w-full flex items-center gap-4 rounded-2xl border-2 p-4 text-left transition-all',\n                    selectedBranch?.id===b.id?'border-transparent':'border-gray-100 bg-white hover:border-gray-200')}\n                  style={selectedBranch?.id===b.id?{borderColor:color,background:color+'08'}:{}}>\n                  <div className=\"h-11 w-11 rounded-xl flex items-center justify-center text-white shrink-0\"\n                    style={{background:color}}>\n                    <MapPin size={18}/>\n                  </div>\n                  <div className=\"flex-1 min-w-0\">\n                    <p className=\"text-sm font-bold text-gray-900\">{b.name}</p>\n                    {b.address&&<p className=\"text-xs text-gray-500 mt-0.5\">{b.address}</p>}\n                    {b.city&&<p className=\"text-xs text-gray-400\">{b.city}</p>}\n                  </div>\n                  <ChevronRight size={16} className=\"text-gray-300 shrink-0\"/>\n                </button>\n              ))}\n            </div>\n          </div>\n        )}\n\n        {/* ── STEP: SERVICE ── */}\n        {currentStep==='service' && (\n          <div className=\"space-y-4 animate-fade-in\">\n            <div>\n              <h2 className=\"text-xl font-bold text-gray-900\">¿Qué servicio querés?</h2>\n              <p className=\"text-sm text-gray-400 mt-1\">Seleccioná el servicio</p>\n            </div>\n            {services.length===0?(\n              <div className=\"rounded-2xl bg-white border border-gray-100 p-6 text-center\">\n                <p className=\"text-sm text-gray-400\">Sin servicios disponibles</p>\n              </div>\n            ):(\n              <div className=\"space-y-2\">\n                {services.map(s=>(\n                  <button key={s.id} onClick={()=>{setSelectedService(s);next()}}\n                    className={cn('w-full flex items-center gap-4 rounded-2xl border-2 p-4 text-left transition-all',\n                      selectedService?.id===s.id?'border-transparent':'border-gray-100 bg-white hover:border-gray-200')}\n                    style={selectedService?.id===s.id?{borderColor:color,background:color+'08'}:{}}>\n                    <div className=\"h-11 w-11 rounded-xl flex items-center justify-center text-white shrink-0\"\n                      style={{background:color}}>\n                      <Scissors size={18}/>\n                    </div>\n                    <div className=\"flex-1 min-w-0\">\n                      <p className=\"text-sm font-bold text-gray-900\">{s.name}</p>\n                      {s.description&&<p className=\"text-xs text-gray-500 mt-0.5 truncate\">{s.description}</p>}\n                    </div>\n                    <div className=\"text-right shrink-0\">\n                      <p className=\"text-sm font-bold\" style={{color}}>{formatPrice(s.price,currency)}</p>\n                      <p className=\"text-xs text-gray-400\">{duration} min</p>\n                    </div>\n                  </button>\n                ))}\n              </div>\n            )}\n            <button onClick={next}\n              className=\"w-full rounded-2xl border border-gray-200 bg-white py-3 text-sm text-gray-500 hover:bg-gray-50\">\n              Continuar sin especificar →\n            </button>\n          </div>\n        )}\n\n        {/* ── STEP: STAFF ── */}\n        {currentStep==='staff' && (\n          <div className=\"space-y-4 animate-fade-in\">\n            <div>\n              <h2 className=\"text-xl font-bold text-gray-900\">¿Con quién querés atenderte?</h2>\n              <p className=\"text-sm text-gray-400 mt-1\">Elegí tu barbero</p>\n            </div>\n            <div className=\"grid grid-cols-2 gap-3\">\n              {staff.map(s=>(\n                <button key={s.id} onClick={()=>{setSelectedStaff(s);next()}}\n                  className={cn('flex flex-col items-center gap-2 rounded-2xl border-2 p-4 transition-all',\n                    selectedStaff?.id===s.id?'border-transparent':'border-gray-100 bg-white hover:border-gray-200')}\n                  style={selectedStaff?.id===s.id?{borderColor:color,background:color+'08'}:{}}>\n                  {s.avatar_url\n                    ? <img src={s.avatar_url} alt={s.name}\n                        className=\"h-16 w-16 rounded-full object-cover ring-2\"\n                        style={selectedStaff?.id===s.id?{ringColor:color}:{ringColor:'transparent'}}/>\n                    : <div className=\"h-16 w-16 rounded-full flex items-center justify-center text-white text-xl font-bold\"\n                        style={{background:s.color}}>\n                        {s.name.slice(0,1).toUpperCase()}\n                      </div>\n                  }\n                  <p className=\"text-sm font-bold text-gray-900 text-center\">{s.name}</p>\n                  <p className=\"text-xs text-gray-400 capitalize\">{s.role}</p>\n                  {selectedStaff?.id===s.id&&(\n                    <div className=\"h-5 w-5 rounded-full flex items-center justify-center text-white\"\n                      style={{background:color}}>\n                      <Check size={11}/>\n                    </div>\n                  )}\n                </button>\n              ))}\n            </div>\n            <button onClick={next}\n              className=\"w-full rounded-2xl border border-gray-200 bg-white py-3 text-sm text-gray-500 hover:bg-gray-50\">\n              Sin preferencia →\n            </button>\n          </div>\n        )}\n\n        {/* ── STEP: DATETIME ── */}\n        {currentStep==='datetime' && (\n          <div className=\"space-y-5 animate-fade-in\">\n            <div>\n              <h2 className=\"text-xl font-bold text-gray-900\">¿Cuándo?</h2>\n              <p className=\"text-sm text-gray-400 mt-1\">Elegí fecha y horario</p>\n            </div>\n\n            {/* Selector de fecha — scroll horizontal */}\n            <div>\n              <p className=\"text-xs font-semibold text-gray-500 mb-3 uppercase tracking-wide\">Fecha</p>\n              <div className=\"flex gap-2 overflow-x-auto pb-2 scrollbar-hide -mx-4 px-4\">\n                {days.map(day=>{\n                  const isSelected = selectedDate?.toDateString()===day.toDateString()\n                  const isPast = day < new Date(new Date().setHours(0,0,0,0))\n                  return(\n                    <button key={day.toISOString()} onClick={()=>!isPast&&setSelectedDate(day)}\n                      disabled={isPast}\n                      className={cn('flex flex-col items-center rounded-2xl p-3 shrink-0 w-14 transition-all',\n                        isPast?'opacity-30 cursor-not-allowed':\n                        isSelected?'text-white':'bg-white border border-gray-100 text-gray-700 hover:border-gray-300')}\n                      style={isSelected?{background:color}:{}}>\n                      <span className=\"text-[10px] font-medium opacity-70\">{DAYS[day.getDay()]}</span>\n                      <span className=\"text-lg font-bold leading-tight\">{day.getDate()}</span>\n                      <span className=\"text-[10px] opacity-70\">{MONTHS[day.getMonth()]}</span>\n                    </button>\n                  )\n                })}\n              </div>\n            </div>\n\n            {/* Horarios */}\n            {selectedDate && (\n              <div>\n                <p className=\"text-xs font-semibold text-gray-500 mb-3 uppercase tracking-wide\">Horario</p>\n                <div className=\"grid grid-cols-4 sm:grid-cols-5 gap-2\">\n                  {timeSlots.map(slot=>{\n                    const isSelected = selectedTime===slot\n                    return(\n                      <button key={slot} onClick={()=>setSelectedTime(slot)}\n                        className={cn('rounded-xl py-2.5 text-sm font-medium transition-all',\n                          isSelected?'text-white':'bg-white border border-gray-100 text-gray-700 hover:border-gray-300 active:scale-95')}\n                        style={isSelected?{background:color}:{}}>\n                        {slot}\n                      </button>\n                    )\n                  })}\n                </div>\n              </div>\n            )}\n\n            {selectedDate&&selectedTime&&(\n              <button onClick={next}\n                className=\"w-full rounded-2xl py-4 text-sm font-semibold text-white transition-all active:scale-[0.98]\"\n                style={{background:color}}>\n                Continuar →\n              </button>\n            )}\n          </div>\n        )}\n\n        {/* ── STEP: CONFIRM ── */}\n        {currentStep==='confirm' && (\n          <div className=\"space-y-5 animate-fade-in\">\n            <div>\n              <h2 className=\"text-xl font-bold text-gray-900\">Confirmá tu reserva</h2>\n              <p className=\"text-sm text-gray-400 mt-1\">Revisá los datos antes de confirmar</p>\n            </div>\n\n            {/* Resumen */}\n            <div className=\"bg-white rounded-2xl border border-gray-100 p-4 space-y-3\">\n              {[\n                { label:'Fecha', value: selectedDate?.toLocaleDateString('es-UY',{weekday:'long',day:'numeric',month:'long'}) },\n                { label:'Hora',  value: selectedTime ? `${selectedTime}hs — ${endTime}hs` : null },\n                { label:'Servicio', value: selectedService?.name },\n                { label:'Barbero',  value: selectedStaff?.name },\n                { label:'Sucursal', value: selectedBranch?.name },\n                { label:'Precio',   value: selectedService?.price ? formatPrice(selectedService.price,currency) : null },\n              ].filter(i=>i.value).map(({label,value})=>(\n                <div key={label} className=\"flex items-center justify-between\">\n                  <span className=\"text-xs text-gray-400\">{label}</span>\n                  <span className=\"text-sm font-semibold text-gray-900\">{value}</span>\n                </div>\n              ))}\n            </div>\n\n            {/* Formulario datos */}\n            <form onSubmit={handleConfirm} className=\"space-y-3\">\n              <div>\n                <label className=\"field-label\">Tu nombre <span className=\"text-red-400\">*</span></label>\n                <div className=\"relative\">\n                  <User size={14} className=\"absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400\"/>\n                  <input type=\"text\" required value={customerName} onChange={e=>setCustomerName(e.target.value)}\n                    placeholder=\"Nombre completo\" className=\"input-base pl-9\"/>\n                </div>\n              </div>\n              <div>\n                <label className=\"field-label\">Teléfono / WhatsApp <span className=\"text-red-400\">*</span></label>\n                <div className=\"relative\">\n                  <Phone size={14} className=\"absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400\"/>\n                  <input type=\"tel\" required value={customerPhone} onChange={e=>setCustomerPhone(e.target.value)}\n                    placeholder=\"099 123 456\" className=\"input-base pl-9\" inputMode=\"numeric\"/>\n                </div>\n              </div>\n              <div>\n                <label className=\"field-label\">Notas <span className=\"text-gray-400 font-normal text-xs\">(opcional)</span></label>\n                <textarea value={notes} onChange={e=>setNotes(e.target.value)} rows={2}\n                  placeholder=\"Aclaraciones, preferencias...\" className=\"input-base resize-none\"/>\n              </div>\n\n              {error&&(\n                <div className=\"rounded-xl bg-red-50 px-4 py-3 text-sm text-red-700\">{error}</div>\n              )}\n\n              <div className=\"fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-sm\n                              border-t border-gray-100 p-4 z-10\">\n                <div className=\"max-w-lg mx-auto\">\n                  <button type=\"submit\" disabled={submitting}\n                    className=\"w-full flex items-center justify-center gap-3 rounded-2xl py-4\n                               text-sm font-semibold text-white disabled:opacity-50 transition-all active:scale-[0.98]\"\n                    style={{background:color}}>\n                    {submitting?<Loader2 size={18} className=\"animate-spin\"/>:<MessageCircle size={18}/>}\n                    {submitting?'Reservando...':business.whatsapp?'Confirmar y avisar por WhatsApp':'Confirmar reserva'}\n                  </button>\n                  <p className=\"text-center text-xs text-gray-400 mt-2\">\n                    {business.whatsapp\n                      ? 'Se abrirá WhatsApp para notificar al local'\n                      : 'Tu turno quedará registrado automáticamente'}\n                  </p>\n                </div>\n              </div>\n            </form>\n          </div>\n        )}\n      </div>\n    </div>\n  )\n}\n"

files["app/api/bookings/route.ts"] = "// app/api/bookings/route.ts\nimport { createServiceClient } from '@/lib/supabase/server'\nimport { NextResponse } from 'next/server'\n\nexport async function POST(req: Request) {\n  try {\n    const body = await req.json()\n    const {\n      businessId, branchId, staffId, productId,\n      customerName, customerPhone, date, startTime, endTime,\n      durationMin, price, notes, source,\n    } = body\n\n    if (!businessId || !customerName || !date || !startTime)\n      return NextResponse.json({ error: 'Datos incompletos' }, { status: 400 })\n\n    const supabase = createServiceClient()\n\n    // Verificar comercio activo\n    const { data: biz } = await supabase\n      .from('businesses').select('id,active').eq('id',businessId).single()\n    if (!biz?.active)\n      return NextResponse.json({ error: 'Comercio no disponible' }, { status: 403 })\n\n    // Verificar conflicto de horario\n    if (staffId) {\n      const { data: conflicts } = await supabase\n        .from('bookings')\n        .select('id,start_time,end_time')\n        .eq('staff_id', staffId)\n        .eq('date', date)\n        .not('status','in','(cancelled,noshow)')\n\n      const hasConflict = (conflicts??[]).some(b => {\n        return startTime < b.end_time && endTime > b.start_time\n      })\n      if (hasConflict)\n        return NextResponse.json({ error: 'Ese horario ya está reservado' }, { status: 409 })\n    }\n\n    // Upsert cliente\n    let customerId: string|null = null\n    if (customerPhone) {\n      const { data: customer } = await supabase\n        .from('customers')\n        .upsert({ business_id:businessId, name:customerName, phone:customerPhone },\n          { onConflict:'business_id,phone' })\n        .select('id').single()\n      customerId = customer?.id ?? null\n    }\n\n    const { data, error } = await supabase.from('bookings').insert({\n      business_id:    businessId,\n      branch_id:      branchId || null,\n      staff_id:       staffId  || null,\n      product_id:     productId|| null,\n      customer_name:  customerName,\n      customer_phone: customerPhone || null,\n      date, start_time:startTime, end_time:endTime,\n      duration_min:   durationMin ?? 30,\n      price:          price ?? null,\n      notes:          notes || null,\n      status:         'pending',\n      source:         source ?? 'store',\n    }).select('id').single()\n\n    if (error) throw error\n\n    return NextResponse.json({ bookingId: data.id })\n  } catch (err) {\n    console.error('[bookings POST]', err)\n    return NextResponse.json({ error: 'Error al crear la reserva' }, { status: 500 })\n  }\n}\n"

for (const [p,c] of Object.entries(files)) {
  const d = path.dirname(p)
  if (!fs.existsSync(d)) fs.mkdirSync(d,{recursive:true})
  fs.writeFileSync(p,c,'utf8')
  console.log('  OK ' + p)
}
